-- Pennsylvania / Philadelphia benefits catalog v2; researched 2026-11-09.
-- Import into a NEW EMPTY SQLite 3 database. No DROP statements or extensions.
-- Rows are benefit pathways, not a count of unique programs or personal entitlements.
-- Read catalog_metadata, cost_class, price_notes, eligibility and caveats together.
-- "Free" can require eligibility or apply only to the listed component.
-- "Nearly free" is reserved for a documented small fee. Unclear costs remain unclear.
-- Public operation alone is not treated as proof of taxpayer funding.
PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE catalog_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE sources(source_id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT NOT NULL,source_type TEXT NOT NULL,checked_on TEXT NOT NULL,notes TEXT NOT NULL);
CREATE TABLE benefits(
 benefit_id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,provider TEXT NOT NULL,
 geography TEXT NOT NULL,cost_class TEXT NOT NULL CHECK(cost_class IN ('free','free_if_eligible','free_selected_services','insurance_zero_cost','free_or_low_cost','sliding_scale','coverage_costs_vary')),
 benefit TEXT NOT NULL,eligibility TEXT NOT NULL,income_limit_percent_fpl REAL,age_rule TEXT,insurance_rule TEXT NOT NULL,
 how_to_access TEXT NOT NULL,caveats TEXT NOT NULL,evidence_status TEXT NOT NULL,checked_on TEXT NOT NULL,priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 3));
CREATE TABLE benefit_sources(benefit_id INTEGER NOT NULL REFERENCES benefits(benefit_id),source_id TEXT NOT NULL REFERENCES sources(source_id),PRIMARY KEY(benefit_id,source_id));
CREATE TABLE locations(location_id INTEGER PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,hours TEXT,access_notes TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(source_id));
CREATE TABLE research_notes(note_id INTEGER PRIMARY KEY,topic TEXT NOT NULL,finding_or_gap TEXT NOT NULL,next_verification TEXT NOT NULL);
CREATE TABLE benefit_details(
benefit_id INTEGER PRIMARY KEY REFERENCES benefits(benefit_id),
cost_tier TEXT NOT NULL CHECK(cost_tier IN ('free','nearly_free','sliding_scale','varies_or_unconfirmed')),
price_notes TEXT NOT NULL,
funding_class TEXT NOT NULL CHECK(funding_class IN ('taxpayer_funded','public_program_funding_unspecified','utility_or_telecom_ratepayer','insurance','charitable_or_provider','mixed','unverified')),
funding_basis TEXT NOT NULL,
funding_source_id TEXT REFERENCES sources(source_id),
availability TEXT NOT NULL,
benefit_form TEXT NOT NULL,
income_metric TEXT,
income_threshold TEXT);

-- catalog_metadata

-- sources

-- benefits

-- benefit_sources

-- locations

-- research_notes

-- benefit_details
CREATE INDEX benefits_category ON benefits(category);
CREATE INDEX benefits_cost ON benefits(cost_class);
CREATE VIEW benefit_catalog AS SELECT b.*,group_concat(s.url,' | ') AS source_urls FROM benefits b JOIN benefit_sources bs USING(benefit_id) JOIN sources s USING(source_id) GROUP BY b.benefit_id;
CREATE VIEW free_without_insurance_pathways AS SELECT * FROM benefit_catalog WHERE cost_class IN ('free','free_if_eligible','free_selected_services');
CREATE VIEW priority_healthcare AS SELECT * FROM benefit_catalog WHERE priority=1;
CREATE VIEW needs_cost_confirmation AS SELECT * FROM benefit_catalog WHERE cost_class IN ('free_or_low_cost','sliding_scale','coverage_costs_vary') OR evidence_status<>'published';
CREATE VIEW expanded_catalog AS SELECT b.*,d.cost_tier,d.price_notes,d.funding_class,d.funding_basis,d.funding_source_id,d.availability,d.benefit_form,d.income_metric,d.income_threshold FROM benefit_catalog b JOIN benefit_details d USING(benefit_id);
CREATE VIEW taxpayer_funded_benefits AS SELECT * FROM expanded_catalog WHERE funding_class='taxpayer_funded';
CREATE VIEW free_and_conditionally_free AS SELECT * FROM expanded_catalog WHERE cost_tier='free';
CREATE VIEW nearly_free_benefits AS SELECT * FROM expanded_catalog WHERE cost_tier='nearly_free';
CREATE VIEW sliding_scale_benefits AS SELECT * FROM expanded_catalog WHERE cost_tier='sliding_scale';
COMMIT;
