INSERT INTO catalog_metadata VALUES('title','Pennsylvania and Philadelphia free-benefit research catalog');
INSERT INTO catalog_metadata VALUES('version','2.0');
INSERT INTO catalog_metadata VALUES('as_of','2026-11-09');
INSERT INTO catalog_metadata VALUES('sql_dialect','SQLite 3; standard SQL, no CLI dot commands or optional extensions');
INSERT INTO catalog_metadata VALUES('scope','Healthcare-first Pennsylvania/Philadelphia catalog expanded to housing, utilities, food, education, legal, disability, employment, recreation, identification and veterans benefits. Researched inventory, not exhaustive.');
INSERT INTO catalog_metadata VALUES('personal_eligibility','Not determined. No age, income, household size, insurance, medical history or immigration details assumed.');
INSERT INTO catalog_metadata VALUES('meaning_of_free','Each row distinguishes free services, eligibility-based free services, selected free components, insurance-covered zero cost, mixed-cost pathways and sliding-scale care.');
INSERT INTO catalog_metadata VALUES('verification','Public official or provider information reviewed online on checked_on date. No provider calls, appointment reservations, claims adjudication or benefit applications performed.');
INSERT INTO catalog_metadata VALUES('source_limitations','Some entries rely on official search-result excerpts; page availability and published offers do not prove real-time appointments, stock, funding or individual approval.');
INSERT INTO catalog_metadata VALUES('income_limits','Percentages are screening guides, not eligibility calculations. Income definitions, deductions, household units and category rules vary. NULL means no numerical threshold recorded, not no limit.');
INSERT INTO catalog_metadata VALUES('citizenship','Residence and citizenship are different. Residency alone does not establish eligibility; citizenship/immigration conditions are stated where published.');
INSERT INTO catalog_metadata VALUES('import','Import into a new empty SQLite database; schema intentionally fails on existing same-name tables rather than deleting data.');
INSERT INTO catalog_metadata VALUES('reuse','Summaries are paraphrased research notes; URLs identify primary sources. Verify costs, network and availability before care.');
INSERT INTO catalog_metadata VALUES('priority','Legacy research ordering only; not personalized and not a medical recommendation.');
INSERT INTO catalog_metadata VALUES('free_view_warning','free_without_insurance_pathways means existing insurance is not necessarily required; clinical, income, enrollment and other conditions still apply.');
INSERT INTO catalog_metadata VALUES('cost_tier_definition','free includes eligibility-based and selected-component zero-cost routes; nearly_free means a documented small charge, not a vague low-cost claim; sliding_scale means income-based fees; varies_or_unconfirmed preserves uncertainty. Always read price_notes and cost_class.');
INSERT INTO catalog_metadata VALUES('funding_definition','taxpayer_funded requires identified tax/government appropriation or federal grant support; public_program_funding_unspecified means government involvement without a verified funding breakdown. Utility/telecom ratepayer charges, insurance, charities and mixed funding are separate.');
INSERT INTO catalog_metadata VALUES('availability_definition','Published offerings are not proof of current appointments, unexhausted funding or individual acceptance. Seasonal and invitation-only restrictions are recorded. Availability is not a reservation.');
INSERT INTO catalog_metadata VALUES('counting_unit','Rows describe benefit pathways, including different providers and materially different components of a program. Row count is not a count of unique government programs, entitlements or benefits one individual qualifies for.');
INSERT INTO catalog_metadata VALUES('income_metrics','FPL percentages and area median income (AMI) percentages are different. Fixed dollar limits include an explicit income metric; household definitions and calculation rules must be verified at intake.');
INSERT INTO catalog_metadata VALUES('new_views','expanded_catalog adds simple cost tier, funding classification/basis, availability, benefit form and income metric. taxpayer_funded_benefits is deliberately conservative, excluding unverified funding streams.');
