INSERT INTO benefits VALUES(1,'Seasonal flu vaccine at City health centers','vaccines','Philadelphia Department of Public Health','Philadelphia','free','Annual flu shot at designated seasonal clinics.','Philadelphia resident age six months or older.',NULL,'6 months and older','No insurance restriction stated','Walk in at Health Centers 2, 6 or 10; bring proof of city residence. See locations table.','Seasonal offer announced November 2, 2026; verify holiday hours, supply and age-appropriate formulation. No insurance restriction stated in notice.','published','2026-11-09',1);
INSERT INTO benefits VALUES(2,'Seasonal COVID-19 vaccine at City health centers','vaccines','Philadelphia Department of Public Health','Philadelphia','free','Seasonal COVID-19 vaccination.','Same residency and age conditions as City seasonal flu clinics.',NULL,'6 months and older','No insurance restriction stated','Walk in at Health Centers 2, 6 or 10 with proof of residence.','Clinician determines appropriateness; seasonal availability.','published','2026-11-09',1);
INSERT INTO benefits VALUES(3,'Free condoms by pickup or mail','sexual_health','Philadelphia Department of Public Health','Philadelphia','free','Condoms; mail programs also distribute lubricant.','Mail delivery within Philadelphia; Take Control teen mail program ages 13-19. Adult route: Philly Keep On Loving.',NULL,NULL,'Not required','Use City condom page to order; pickup at Health Center 1 or current partner sites.','Health Center 5 is listed as closed on the program homepage despite older pickup listings.','published','2026-11-09',1);
INSERT INTO benefits VALUES(4,'PA Family Planning Services coverage','birth_control','Pennsylvania DHS','Pennsylvania','free_or_low_cost','Contraception and related visits, tests and supplies through enrolled providers.','PA resident; not pregnant; not otherwise Medicaid eligible; citizenship or satisfactory immigration status required.',215.0,'Any age subject to service rules','See eligibility','Apply through PA coverage service or COMPASS; ask provider to check Family Planning Services eligibility.','Public eligibility page says free or low-cost. Confirm covered method and provider billing; not general comprehensive insurance.','published','2026-11-09',1);
INSERT INTO benefits VALUES(5,'Insurance-covered prescription contraception','birth_control','Marketplace and other qualifying health plans','Pennsylvania / federal coverage','insurance_zero_cost','Covered prescribed contraceptive methods and counseling without cost-sharing.','Enrollment in qualifying plan; in-network provider; applicable prescription and plan rules.',NULL,NULL,'Qualifying health insurance required','Ask plan and prescriber which method and pharmacy are covered at zero cost.','Premiums remain separate. Exceptions apply to some plans; not every brand or OTC purchase is automatically free; vasectomy is not included in this mandate.','published','2026-11-09',1);
INSERT INTO benefits VALUES(6,'City family planning clinics','birth_control','City health centers','Philadelphia','sliding_scale','Pills, injections, rings, IUDs, implants, emergency contraception and reproductive care.','Health-center patients; fees depend on insurance, income and family size.',NULL,NULL,'See eligibility','Schedule with a City health center; walk-ins accepted.','Uninsured patients are charged an income-based fee; residency alone does not make services free.','published','2026-11-09',1);
INSERT INTO benefits VALUES(7,'AccessMatters family planning network','birth_control','AccessMatters','Southeastern Pennsylvania','free_or_low_cost','Confidential reproductive and family planning visits, virtual or in person.','Adults and teens; provider-specific eligibility and fee assessment.',NULL,NULL,'See eligibility','Use Find Services directory and ask selected clinic about no-cost eligibility.','Network is described as no-cost or low-cost; verify contraception, testing and follow-up costs.','published','2026-11-09',1);
INSERT INTO benefits VALUES(8,'Health Center 1 STI testing and treatment','sexual_health','Philadelphia Department of Public Health','Philadelphia','free','Confidential STI evaluation, testing and treatment.','Clinic page says people older than 13; ask clinic for younger-patient policy.',NULL,'Older than 13 per clinic page','No insurance requirement stated','Walk-in clinic: 1930 S. Broad St., 2nd floor; 215-685-6570.','Services depend on clinical assessment and clinic capacity.','published','2026-11-09',1);
INSERT INTO benefits VALUES(9,'Philly TelePrEP','hiv_prevention','Philly Keep On Loving','Philadelphia','free_or_low_cost','Remote PrEP care and help arranging medication, labs and payment assistance.','Philadelphia residents; clinician must assess HIV status and suitability; accepts insured or uninsured.',NULL,NULL,'Insured or uninsured','Start through TelePrEP website or sexual-health helpline 215-985-2437.','Overview says free; detailed FAQ says little or no cost. Confirm medication, labs, visits, delivery and chosen formulation individually.','conflicting_cost_language','2026-11-09',1);
INSERT INTO benefits VALUES(10,'Philadelphia FIGHT PrEP access','hiv_prevention','Philadelphia FIGHT','Philadelphia','free_or_low_cost','PrEP prescribing, labs, follow-up and cost-navigation support.','Clinical eligibility; no insurance or income required to seek care.',NULL,NULL,'Insured or uninsured','Call 215-545-7737; clinic program at 1207 Chestnut St.','Provider says Medicaid fully covers visits, labs and medicine; private plans may have zero or minimal costs. Uninsured assistance is individualized.','published','2026-11-09',1);
INSERT INTO benefits VALUES(11,'Mazzoni PrEP navigation and free screening pathway','hiv_prevention','Mazzoni Center','Philadelphia','free_selected_services','Navigation program lists free rapid HIV tests, STI screening, condoms and lubricant; links to PrEP.','Navigation program: men who have sex with men or people of trans experience, age 16+.',NULL,'16 and older','See eligibility','Call 215-563-0652 ext. 110 to confirm navigation intake and test access.','Free navigation-linked tests do not establish free PrEP medicine, labs or general medical visits.','published','2026-11-09',2);
INSERT INTO benefits VALUES(12,'Washington West sexual health care','sexual_health','Mazzoni Center','Philadelphia','sliding_scale','Sexual healthcare including PrEP, STI services and contraception.','Insurance and/or sliding-fee discount program per provider.',NULL,NULL,'See eligibility','Use provider appointment links; confirm costs before appointment.','CDC directory lists some free services, but provider page requires insurance/sliding scale. Confirm any specific free testing offer directly.','conflicting_cost_language','2026-11-09',2);
INSERT INTO benefits VALUES(13,'Vaccines for Adults at Risk','vaccines','Philadelphia Immunization Program','Philadelphia','free_if_eligible','Program vaccines with no out-of-pocket cost at participating providers.','Uninsured adults at high risk of vaccine-preventable disease.',NULL,NULL,'Uninsured','Ask clinic whether it participates in VFAAR and has the needed vaccine.','Eligible products and risk criteria vary; not all adult vaccines at every provider are free.','published','2026-11-09',2);
INSERT INTO benefits VALUES(14,'Mpox vaccination for uninsured adults','vaccines','Philadelphia Immunization Program','Philadelphia','free_if_eligible','Mpox vaccination through participating program providers.','Uninsured adults meeting exposure-risk and clinical criteria.',NULL,NULL,'Uninsured','Contact an enrolled provider via Philadelphia Immunization Program.','Confirm stock and eligibility; insured patients generally use their plan.','published','2026-11-09',2);
INSERT INTO benefits VALUES(15,'Vaccines for Children','vaccines','CDC and participating PA/Philadelphia providers','Pennsylvania','free_selected_services','No-cost program vaccine doses for eligible children.','Under 19; Medicaid-eligible, uninsured, American Indian/Alaska Native, or qualifying underinsured children.',NULL,'Under 19','See eligibility','Use a VFC provider; underinsured children generally need an FQHC, rural health clinic or authorized site.','Vaccine itself is free. Other visit charges may apply; vaccination cannot be denied for inability to pay administration fee.','published','2026-11-09',2);
INSERT INTO benefits VALUES(16,'COVID-19 home test kits','testing','City Resource Hubs / NCACs','Philadelphia','free','At-home COVID test kits.','Residents accessing participating distribution sites.',NULL,NULL,'No insurance requirement stated','Use current Neighborhood Community Action Center locator; check stock before travel.','Hubs relocated/expanded in 2026; older location lists may be obsolete.','published','2026-11-09',2);
INSERT INTO benefits VALUES(17,'HIV self-test kits','sexual_health','City Resource Hubs / NCACs','Philadelphia','free','Take-home HIV self-test kits.','Residents accessing participating sites.',NULL,NULL,'No insurance requirement stated','Check current NCAC locations and supplies.','Availability varies; testing windows and follow-up should be discussed with a clinician.','published','2026-11-09',2);
INSERT INTO benefits VALUES(18,'Naloxone by mail','harm_reduction','PA DDAP / Prevention Point Pittsburgh / NEXT Distro','Pennsylvania','free','Overdose-reversal naloxone for personal use.','Pennsylvania residents; Philadelphia has a dedicated request route.',NULL,NULL,'Not required','Complete short training and request form linked from PA service page.','Supply and fulfillment may vary.','published','2026-11-09',2);
INSERT INTO benefits VALUES(19,'Overdose prevention pickup supplies','harm_reduction','PA DDAP partner distribution sites','Pennsylvania','free','Naloxone and fentanyl/xylazine test strips at participating sites.','People seeking personal overdose-prevention supplies.',NULL,NULL,'Not required','Use PA free-supply locator; Philadelphia residents can use local distribution routes.','Ask for current stock; test strips do not establish that a substance is safe.','published','2026-11-09',2);
INSERT INTO benefits VALUES(20,'Tobacco quit coaching','tobacco_cessation','PA Free Quitline','Pennsylvania','free','Confidential telephone coaching and web/text support.','People using tobacco; tailored youth and pregnancy programs available.',NULL,NULL,'No insurance requirement stated','Call 1-800-QUIT-NOW or enroll through PA service page.','Counseling is free; separate medical eligibility applies to medication.','published','2026-11-09',2);
INSERT INTO benefits VALUES(21,'Nicotine replacement through Quitline','tobacco_cessation','PA Free Quitline','Pennsylvania','free_if_eligible','Nicotine replacement therapy for eligible enrollees.','Quitline enrollment and medical eligibility.',NULL,NULL,'See eligibility','Ask Quitline about available formulations and supply duration.','Not an unlimited prescription benefit; specific products and refill terms need confirmation.','published','2026-11-09',2);
INSERT INTO benefits VALUES(22,'Breast cancer screening and diagnostic follow-up','cancer_screening','PA-BCCEDP / AccessMatters','Pennsylvania','free_if_eligible','Eligible mammography, indicated MRI and follow-up diagnostic testing.','Generally ages 40-64; anatomical/clinical eligibility; uninsured or underinsured; no Medicaid or Medicare B, with limited exceptions.',250.0,'Generally 40-64','See eligibility','Philadelphia-area intake: AccessMatters 1-800-848-3367.','Exceptions for younger/older people may apply. Intake should confirm current dollar limits.','published','2026-11-09',2);
INSERT INTO benefits VALUES(23,'Cervical cancer screening and diagnostic follow-up','cancer_screening','PA-BCCEDP / AccessMatters','Pennsylvania','free_if_eligible','Eligible Pap/HPV screening and abnormal-result follow-up.','Generally ages 21-64; relevant anatomy; same financial/insurance rules as PA-BCCEDP breast screening.',250.0,'Generally 21-64','See eligibility','Contact AccessMatters 1-800-848-3367.','Family Planning-only Medicaid may qualify; routine screening through other insurance is a different pathway.','published','2026-11-09',2);
INSERT INTO benefits VALUES(24,'Breast or cervical cancer treatment coverage','health_coverage','Pennsylvania DHS BCCPT','Pennsylvania','free_if_eligible','Healthcare during qualifying breast/cervical cancer or precancer treatment, including unrelated medical needs.','Qualifying diagnosis/treatment need; under 65; uninsured/no creditable insurance; PA residence and citizen/eligible noncitizen rules.',NULL,'Under 65','See eligibility','Apply through DHS BCCPT process with treating provider.','No income or resource limit stated; eligibility still requires clinical and administrative determination.','published','2026-11-09',2);
INSERT INTO benefits VALUES(25,'Medical Assistance / Medicaid','health_coverage','Pennsylvania DHS','Pennsylvania','coverage_costs_vary','Comprehensive medical and behavioral health coverage.','Adult expansion route generally uses 138% FPL; other categories have different rules; residence and citizenship/immigration criteria apply.',138.0,NULL,'See eligibility','Apply via COMPASS or 1-866-550-4355.','2026 one-person adult limit listed as $22,025/year. Do not assume every service has zero copay. State flags rule changes for 2027.','published','2026-11-09',2);
INSERT INTO benefits VALUES(26,'Free-tier CHIP','health_coverage','Pennsylvania DHS CHIP','Pennsylvania','free_if_eligible','Children and teen health insurance in the free income tier.','Uninsured PA residents under 19, citizen/national/qualified immigrant, not eligible for Medicaid; household income determines tier.',NULL,'Under 19','Uninsured','Apply through state CHIP service; agency routes children to appropriate coverage.','Higher-income tiers have premiums/copays. Do not use outdated income tables to establish free eligibility.','published','2026-11-09',2);
INSERT INTO benefits VALUES(27,'Medical Assistance transportation','transport_health','Pennsylvania MATP','Pennsylvania','free_if_eligible','Non-emergency transport to covered medical services.','Medical Assistance recipient with unmet transportation need; local enrollment required.',NULL,NULL,'Medical Assistance','Use state MATP page to contact Philadelphia county provider and arrange trips.','Not an ambulance service; advance booking, destination and covered-service rules apply.','published','2026-11-09',2);
INSERT INTO benefits VALUES(28,'HIV medication and selected lab assistance','hiv_treatment','PA Special Pharmaceutical Benefits Program','Pennsylvania','free_if_eligible','Covered medicines, eligible medication cost-sharing, some labs and selected Medicare premiums.','PA resident with HIV diagnosis; income at or below 350% FPL; not eligible for Medicaid pharmacy benefits.',350.0,NULL,'See eligibility','Apply through SPBP MyRx enrollment; 1-800-922-9384.','Payer of last resort with formularies/networks; this is HIV treatment assistance, not a general PrEP program. Older 500% threshold is superseded.','published','2026-11-09',2);
INSERT INTO benefits VALUES(29,'City dental services','dental','City health centers','Philadelphia','sliding_scale','Basic and emergency dentistry for enrolled patients.','Health-center enrollment and fee assessment.',NULL,NULL,'See eligibility','Schedule a City dental appointment; urgent walk-ins accepted as capacity allows.','Uninsured patients pay a fee based on income/family size. Not universally free.','published','2026-11-09',2);
INSERT INTO benefits VALUES(30,'CCP dental hygiene teaching clinic','dental','Community College of Philadelphia','Philadelphia','free','Supervised dental hygiene clinic care.','Patient acceptance depends on teaching-clinic screening and availability.',NULL,NULL,'See eligibility','Contact college dental hygiene program for current patient intake.','College confirms a free clinic; exact current procedures and appointment availability need confirmation. Do not assume fillings, extractions or emergency dentistry are included.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(31,'United Community Clinic','primary_care','University of Pennsylvania student-run clinic','Philadelphia','free','Basic primary care, prevention, HIV screening, work physicals and basic lab tests.','Community patients accepted through clinic scheduling and assessment.',NULL,NULL,'See eligibility','Call 215-746-5135 or submit website request; Monday evening clinics.','Limited scope and capacity; advanced or long-term care may require referral with separate costs.','published','2026-11-09',2);
INSERT INTO benefits VALUES(32,'Penn Medicine charity care','hospital_assistance','Penn Medicine','Philadelphia region','free_if_eligible','Free eligible medically necessary care for approved applicants; partial discounts above threshold.','Generally family income below 300% FPL, limited/no insurance, no other payment source, within 50 miles; apply for Medical Assistance first.',300.0,NULL,'See eligibility','Request financial assistance application; 1-877-433-5299; summary says apply within one year of treatment.','Approval required; confirm participating provider/bill coverage. Other Penn affiliates may use different policies.','published','2026-11-09',2);
INSERT INTO benefits VALUES(33,'Insurance-covered preventive screening','preventive_care','Qualifying health plans','Pennsylvania / federal coverage','insurance_zero_cost','Specified preventive services without cost-sharing when coverage conditions are met.','Qualifying plan and in-network care; age, risk and screening-frequency rules vary by service.',NULL,NULL,'Qualifying insurance required','Ask insurer and provider to confirm preventive coding and all associated fees.','Not all tests, diagnostic follow-ups or visits are preventive; premiums and unrelated services remain separate.','published','2026-11-09',2);
INSERT INTO benefits VALUES(34,'Free online mental-health screening','mental_health','Healthy Minds Philly / DBHIDS','Philadelphia / online','free','Anonymous online emotional/mental-health screening and resource links.','Public online access.',NULL,NULL,'Not required','Use Healthy Minds Philly via DBHIDS page.','Screening is not diagnosis, therapy or a guarantee of free treatment.','published','2026-11-09',2);
INSERT INTO benefits VALUES(35,'Mental Health First Aid training','mental_health','Philadelphia DBHIDS','Philadelphia','free_if_eligible','Mental Health First Aid educational training.','People who live, work or study in Philadelphia.',NULL,NULL,'See eligibility','Register through DBHIDS / Healthy Minds Philly.','Training availability varies; not individual clinical treatment.','published','2026-11-09',2);
INSERT INTO benefits VALUES(36,'Community behavioral-health screening kiosks','mental_health','Healthy Minds Philly','Philadelphia','free','Anonymous screening and local resource information.','Access to participating kiosk location.',NULL,NULL,'See eligibility','Program lists Drexel Recreation Center and 11th Street Family Health Services; confirm site access.','Not diagnosis or therapy; current kiosk operation not independently confirmed.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(37,'Philly Families CAN support referral','pregnancy_family','Philadelphia maternal/child health programs','Philadelphia County','free','Connection to voluntary pregnancy, parenting and home-visiting support.','Pregnant people, parents and families; receiving-program criteria vary.',NULL,NULL,'See eligibility','Contact Philly Families CAN through program site.','Referral does not guarantee immediate placement or replace prenatal care.','published','2026-11-09',2);
INSERT INTO benefits VALUES(38,'Nurse-Family Partnership','pregnancy_family','PHMC Philadelphia NFP','Philadelphia','free_if_eligible','Personal nurse home-visiting support for first-time pregnant people.','First pregnancy and program enrollment criteria; confirm pregnancy-stage and income rules with intake.',NULL,NULL,'See eligibility','Enroll directly with PHMC or through Philly Families CAN.','Current capacity and detailed eligibility require intake confirmation.','published','2026-11-09',2);
INSERT INTO benefits VALUES(39,'Breastfeeding and infant-feeding support','pregnancy_family','Philly Loves Families / Pacify','Philadelphia','free','App-based live infant-feeding and breastfeeding support.','Philadelphia families per City family-health resource page.',NULL,NULL,'See eligibility','Use Pacify enrollment instructions linked by Philly Loves Families.','Verify current local access instructions; service is support, not emergency care.','published','2026-11-09',2);
INSERT INTO benefits VALUES(40,'Safe-sleep crib assistance','pregnancy_family','Philadelphia Public Health / Maternity Care Coalition','Philadelphia','free_if_eligible','Pack n Play crib through safe-sleep support programs.','Families needing safe infant sleep space; program-specific screening/class requirements.',NULL,NULL,'See eligibility','Request through City infant-support page or Philly Families CAN.','Older source; stock, enrollment and any class requirements must be confirmed.','older_source_confirm_intake','2026-11-09',2);
INSERT INTO benefits VALUES(41,'WIC nutrition and food support','nutrition','Pennsylvania WIC','Pennsylvania','free_if_eligible','Supplemental foods, nutrition services, feeding support and referrals.','Pregnant/postpartum/breastfeeding participants, infants and children under 5; PA residence, nutritional/medical risk and income rules.',185.0,'Pregnancy/postpartum categories; children under 5','See eligibility','Call 1-800-WIC-WINS or use state pre-application.','185% FPL guideline; categorical income eligibility may apply. Not unrestricted grocery reimbursement.','published','2026-11-09',2);
INSERT INTO benefits VALUES(42,'TB testing and evaluation','infectious_disease','Philadelphia Tuberculosis Control Program','Philadelphia','free','TB testing and medical evaluation through City TB program.','Program assessment and appointment; ask whether school/work screening is accepted.',NULL,NULL,'See eligibility','Lawrence F. Flick Memorial Center, 1930 S. Broad St.; 215-685-6873.','Do not assume unrelated tests or every commercial testing location are free.','published','2026-11-09',2);
INSERT INTO benefits VALUES(43,'TB medication and observed therapy','infectious_disease','Philadelphia Tuberculosis Control Program','Philadelphia','free_if_eligible','TB medicines, clinical evaluation and directly observed therapy.','Confirmed/suspected TB or latent infection needing program care; referral and assessment.',NULL,NULL,'See eligibility','Treating provider refers to Lawrence Flick clinic.','Clinician-directed treatment; specific care determined by the program.','published','2026-11-09',2);
INSERT INTO benefits VALUES(44,'Period Pantry menstrual products','menstrual_health','Jefferson Health Plans','Philadelphia','free','Pads, tampons, menstrual-health information and navigation.','Open to community members, not only plan members.',NULL,NULL,'Membership not required','Community Wellness Center, 6232 Market St.; 833-435-1995 for hours.','Published Friday hours contain an apparent typo; confirm before visiting. Supplies vary.','published','2026-11-09',2);
INSERT INTO benefits VALUES(45,'Grab N Flow supplies','menstrual_health','Grab N Flow','Philadelphia area','free','Menstrual and postpartum care supplies through community sheds.','Individuals needing supplies.',NULL,NULL,'See eligibility','Use organization location map to find a current distribution point.','Volunteer-supported stock and product selection vary.','published','2026-11-09',2);
INSERT INTO benefits VALUES(46,'BenePhilly benefits counseling','benefits_navigation','City / BenePhilly partners','Philadelphia','free','One-on-one benefits applications and follow-up.','Philadelphia residents.',NULL,NULL,'See eligibility','Call 800-994-5537 for referral to a center.','Counseling is free; each underlying benefit has separate eligibility.','published','2026-11-09',1);
INSERT INTO benefits VALUES(47,'Free groceries and prepared meals','food','City food finder / community providers','Philadelphia','free','Food pickup and ready-to-eat meals at listed sites.','Site-specific eligibility; public food/general/student sites described as not requiring ID.',NULL,NULL,'See eligibility','Use City food finder and confirm hours before traveling.','Older-adult and other targeted sites may have additional conditions; supply varies.','published','2026-11-09',2);
INSERT INTO benefits VALUES(48,'Free Library card and borrowing','library','Free Library of Philadelphia','Pennsylvania','free','Library access and borrowing through free public-library membership.','Pennsylvania residents; online instant registration for adults/teens; children 12 or younger apply with guardian in person.',NULL,NULL,'See eligibility','Apply through official Free Library registration page.','Identity/residency validation and item-specific borrowing limits apply; replacement or other special charges not assessed here.','published','2026-11-09',2);
INSERT INTO benefits VALUES(49,'POWER Library electronic resources','library','State Library of Pennsylvania','Pennsylvania','free','State-funded online library resources through POWER e-card.','Pennsylvania residents, including those outside eligible reciprocal-library service areas.',NULL,NULL,'See eligibility','Follow Get a Free POWER Library E-Card on state program page.','Reciprocal physical borrowing has separate municipality/library participation rules.','published','2026-11-09',2);
INSERT INTO benefits VALUES(50,'Smoke alarms and installation','home_safety','Philadelphia Fire Department','Philadelphia','free_if_eligible','Smoke alarms installed in qualifying homes.','Owner-occupied one- or two-family home in Philadelphia.',NULL,NULL,'See eligibility','Request via Philly311.','City says installation may take up to 90 days. Rental-property owners have separate alarm responsibilities.','published','2026-11-09',2);
INSERT INTO benefits VALUES(51,'Senior SEPTA fare program','transport','SEPTA','Philadelphia region','free_if_eligible','Eligible senior travel using a Senior Fare Card.','Age 65 or older; obtain approved senior fare card.',NULL,'65 and older','See eligibility','Apply through SEPTA or participating state legislative district office.','Check route and interstate Regional Rail conditions; do not assume paratransit/shared rides are free.','published','2026-11-09',2);
INSERT INTO benefits VALUES(52,'Adult education classes','education','City-funded adult education providers','Philadelphia','free','Reading, writing, math, ESL, GED/HiSET preparation and basic computer classes.','Generally age 16+; provider enrollment rules and availability.',NULL,'16 and older','See eligibility','Call 1-833-750-5627; interpreters available.','Class access does not imply all credential exam fees are paid.','published','2026-11-09',2);
INSERT INTO benefits VALUES(53,'Digital skills classes','education','City of Philadelphia partners','Philadelphia','free','Classes to improve digital skills.','Philadelphia residents; individual class enrollment rules.',NULL,NULL,'See eligibility','Use City digital skills class finder.','Schedule, level, equipment and availability vary.','published','2026-11-09',2);
INSERT INTO benefits VALUES(54,'Free tax preparation referral','financial_support','VITA / City nonprofit partners','Philadelphia','free_if_eligible','Eligible tax-return preparation and credit-claim assistance.','Income, return complexity and provider rules; confirm current filing-year requirements.',NULL,NULL,'See eligibility','Use City free-tax-prep directory and current provider intake.','City guide is older; no historical dollar limit treated as current. Appointment availability can be seasonal.','older_source_confirm_intake','2026-11-09',2);
INSERT INTO benefits VALUES(55,'Right to Counsel eviction representation','legal','Philadelphia Right to Counsel','Philadelphia','free_if_eligible','Attorney for qualifying eviction, tenancy termination or subsidy termination proceedings.','Income at or below 200% FPL and covered proceeding; eligible ZIP codes 19121, 19124, 19131, 19132, 19134, 19139, 19141, 19144, 19153, 19154.',200.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call Philadelphia Eviction Prevention Project at 267-443-2500.','ZIP coverage may expand. Immigration status does not affect this program; other legal-aid routes exist outside covered ZIPs.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(56,'Tenant legal advice and eviction hotline','legal','Philadelphia Eviction Prevention Project','Philadelphia','free','Free tenant information, legal advice, referrals and possible representation.','Philadelphia tenants facing housing problems; representation has additional eligibility and capacity limits.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 267-443-2500.','Distinct from the ZIP-specific guaranteed Right to Counsel; a hotline call does not guarantee a lawyer.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(57,'LIHEAP heating cash grant','utilities','Pennsylvania DHS','Pennsylvania','free_if_eligible','Heating assistance of $200-$1,000 paid to a utility or fuel supplier.','Income-eligible households responsible for heating costs; renters and homeowners may qualify.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply through COMPASS or county assistance office.','Grant does not cover all annual heating costs; confirm household rules and available funds.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(58,'LIHEAP crisis heating assistance','utilities','Pennsylvania DHS','Pennsylvania','free_if_eligible','Help addressing a qualifying heating emergency, including threatened loss of heat.','LIHEAP financial eligibility plus a qualifying crisis; county determines covered response.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Contact county assistance office through LIHEAP application page.','Separate crisis eligibility; not an unlimited emergency repair or fuel entitlement.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(59,'Weatherization Assistance Program','housing','PA DCED / Philadelphia PHDC','Pennsylvania; Philadelphia local intake','free_if_eligible','Home energy assessment and approved insulation, air sealing and efficiency improvements.','Generally income at or below 200% FPL or qualifying categorical eligibility; owners and renters; building assessment required.',200.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Philadelphia: PHDC 215-448-2130 or phdc.intake@phdc.phila.gov.','Work depends on assessment, funding and property readiness; not general cosmetic renovation.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(60,'Basic Systems Repair Program','housing','PHDC','Philadelphia','free_if_eligible','Approved emergency electrical, plumbing, heating, structural or roof repairs.','Income-eligible owner-occupied single-family Philadelphia home; PHDC lists 100% AMI threshold.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply to PHDC Basic Systems Repair Program.','Waitlists, condition and ownership review apply. AMI is area median income, not federal poverty level.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(61,'Adaptive Modifications Program','disability_housing','PHDC','Philadelphia','free_if_eligible','Accessibility modifications to help a person with a permanent physical disability remain at home.','Permanent physical disability and household/property eligibility; PHDC lists 80% AMI threshold.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Contact PHDC for Adaptive Modifications intake.','Assessment determines modifications; ownership or landlord authorization and waiting periods may apply.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(62,'Heater Hotline emergency repair','housing','Energy Coordinating Agency','Philadelphia','free_if_eligible','Emergency repair of an eligible home heating system.','Owner-occupied single-family home; no other property; income at or below 150% FPL.',150.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 215-568-7190.','Provider introduction mentions replacement, but detailed rules say repair only, excluding new heating systems and water heaters. Confirm scope; renters excluded.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(63,'City-funded housing counseling','housing_navigation','DHCD partner counseling agencies','Philadelphia','free','Individual or group counseling on foreclosure, home buying, housing rights, repairs and tenant issues.','Residents seeking housing counseling; individual agencies may specialize.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use City counseling-agency map and contact a participating counselor.','Counseling does not itself provide repair money, a mortgage or legal representation.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(64,'Financial Empowerment Center counseling','financial_navigation','City / Clarifi','Philadelphia','free','Confidential one-on-one professional help with budgets, credit, banking and financial goals.','Open to people seeking financial counseling; no income test stated.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 855-346-7445 or schedule through City page.','Advice service; not a cash grant, debt cancellation or investment return guarantee.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(65,'Tiered Assistance Program water bills','utilities','Philadelphia Water Department','Philadelphia','sliding_scale','Income-based water bill and potential arrears relief under program rules.','Income eligibility or qualifying special hardship; generally up to 150% FPL, with some higher-income routes.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply through City water customer assistance portal.','Ongoing bill remains payable. Debt forgiveness has conditions; not free water.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(66,'PHLpreK','early_childhood','City PHLpreK providers','Philadelphia','free_if_eligible','Free prekindergarten at participating providers.','Philadelphia resident age 3 or 4 by September 1 for the school year; no income eligibility limit.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 844-745-7735 or enroll with a participating provider; show age and residence documents.','Seats and schedules vary; extended care is not automatically included.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(67,'Early Intervention evaluation and therapy','child_health','Pennsylvania early intervention system','Pennsylvania','free_if_eligible','Developmental evaluation and eligible early-intervention services for children with delays or disabilities.','Birth through kindergarten-entry age; evaluation determines eligibility and service plan.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call CONNECT at 800-692-7288 for local referral.','Therapy follows the individualized plan; not unlimited private treatment. No family fee for required EI services.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(68,'SNAP food benefits','food_assistance','Pennsylvania DHS / USDA','Pennsylvania','free_if_eligible','Monthly benefits for eligible food purchases.','Household income and other eligibility rules apply, including applicable immigration and work requirements.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply via COMPASS or county assistance office.','Screening limit is not an automatic award; deductions and household rules affect the amount.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(69,'SUN Bucks summer grocery benefits','food_assistance','Pennsylvania DHS / USDA','Pennsylvania','free_if_eligible','$120 summer grocery benefit per eligible child for 2026.','School-age child meeting program criteria; many children qualify automatically; others require application.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use PA SUN Bucks eligibility/application portal.','2026 application deadline was August 31. Late applications may be considered for the next summer, not a guaranteed current-year payment.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(70,'School District breakfast and lunch','school_meals','School District of Philadelphia','Philadelphia','free_if_eligible','School breakfast and lunch without student meal charges.','Students in the School District of Philadelphia.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use the student school meal service.','School calendar and meals offered govern availability; charter/private school arrangements must be checked separately.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(71,'Senior Food Box Program','food_assistance','Pennsylvania Agriculture / USDA','Pennsylvania','free_if_eligible','Monthly package of supplemental nutritious foods.','Age 60 or older and income at or below 150% FPL; local enrollment.',150.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-468-2433 or find local distribution partner.','Supplemental food only; site capacity and delivery options differ. Use current income table rather than old dollar figures.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(72,'Summer meals for children and teens','food_assistance','City and participating summer meal sites','Philadelphia','free_if_eligible','Meals at participating summer feeding sites.','Youth age 18 and younger at open sites; site type may affect access.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use City summer-meal locator when season opens.','Summer program, not a year-round walk-in meal promise; verify dates and site rules.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(73,'Drinking-water lead and copper testing','environmental_health','Philadelphia Water Department','Philadelphia','free','Water sample kit and testing for lead/copper or other investigated water-quality concerns.','Philadelphia Water Department customers.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 215-685-6300 to arrange testing.','Sample instructions matter; a water test does not inspect all paint or dust hazards in a home.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(74,'Child lead exposure home investigation','environmental_health','City Lead and Healthy Homes Program','Philadelphia','free_if_eligible','Education and licensed home inspection following a qualifying elevated child blood-lead result.','Qualifying child blood-lead result; City page uses 3.5 micrograms/deciliter trigger.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 215-685-2788 or follow referral after child blood test.','Not a universal free inspection for every purchaser or landlord.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(75,'Lead hazard remediation assistance','environmental_health','City Lead and Healthy Homes Program','Philadelphia','free_or_low_cost','Possible funding to remove qualifying residential lead hazards.','Property, household, income and hazard criteria must be assessed by the program.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Contact 215-685-2788 for remediation eligibility.','An inspection does not guarantee remediation funding; confirm any owner obligations and grant conditions.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(76,'Invited water service-line verification and replacement','environmental_health','Philadelphia Water Department','Philadelphia','free_if_eligible','Free service-line investigation, with replacement of qualifying lead/galvanized lines found through this program.','Only selected properties invited into the verification project.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Respond to official Water Department invitation; verify notice through PWD.','Not open enrollment and not a universal free replacement offer.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(77,'PA MEDI Medicare counseling','health_navigation','Pennsylvania Department of Aging / local agencies','Pennsylvania','free','Confidential Medicare enrollment, plan comparison and appeals counseling.','People with Medicare or seeking Medicare information, including caregivers.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-783-7067.','Counseling is free; insurance premiums and treatment costs depend on chosen coverage.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(78,'PACE and PACENET prescription assistance','prescription_assistance','Pennsylvania Department of Aging','Pennsylvania','free_or_low_cost','Reduced out-of-pocket prescription costs for eligible older residents.','Age 65+; PA resident at least 90 days; no Medicaid prescription benefit. PACE annual income limits $14,500 single/$17,700 couple; PACENET up to $33,500/$41,500.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-225-7223 or apply through state service page.','Prior-calendar-year income and program calculation rules apply. Confirm current drug copay, formulary and premium arrangements.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(79,'Special Kids Network navigation','child_health','Pennsylvania Department of Health','Pennsylvania','free','Information and referrals for children and youth with special healthcare needs.','Children/youth birth through age 21 and their families.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-986-4550.','Navigation does not make every referred service free.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(80,'HIV CD4 and viral-load laboratory assistance','hiv_treatment','Pennsylvania Department of Health','Pennsylvania','free_if_eligible','Confidential CD4 and viral-load testing for eligible people living with HIV.','SPBP or Ryan White Part B eligibility, or no other means to pay under program criteria.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use the state HIV services page and treating HIV provider.','These are HIV treatment-monitoring labs, not routine HIV screening or PrEP labs.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(81,'Esperanza free HIV testing','sexual_health','Esperanza Health Center','Philadelphia','free','HIV testing at participating Esperanza sites.','People seeking HIV testing; confirm age and consent requirements with site.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 215-302-3600; provider lists weekday walk-in testing at three sites.','Free HIV test does not mean all general medical care or other tests are free.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(82,'Abortion Liberation Fund assistance','reproductive_health','Abortion Liberation Fund of PA','Philadelphia and served regional counties','free_or_low_cost','Financial assistance toward an abortion for people unable to afford the full cost.','Residence in served counties or procedure at a served regional provider; fund determines award.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Schedule clinic appointment first, then call 215-564-6622.','Assistance may not cover full cost. A historical City grant does not establish current taxpayer funding.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(83,'Pennsylvania Health Law Project legal help','legal_health','Pennsylvania Health Law Project','Pennsylvania','free_if_eligible','Legal advice or advocacy concerning Medicaid and healthcare access for qualifying people.','Low-income people, older adults and people with disabilities; matter and intake criteria apply.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-274-3258; check current intake hours.','Representation is subject to acceptance; this is not a medical treatment service.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(84,'Uninsured behavioral-health access assistance','mental_health','Philadelphia DBHIDS','Philadelphia','free_or_low_cost','Referral and assessment route for people needing behavioral healthcare without adequate coverage.','Philadelphia residents uninsured or underinsured; treatment eligibility assessed individually.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call DBHIDS at 215-685-5400.','Referral is not proof that all therapy, medication or hospital care will be free.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(85,'Spectrum community health and behavioral care','primary_care','Spectrum Health Services','Philadelphia','sliding_scale','Primary, dental, reproductive and behavioral healthcare through a community health center.','Patients assessed for insurance and income-based discounts.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 215-471-2761 or contact a Spectrum site.','Income-based fees; confirm service, minimum charge and referral costs before care.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(86,'Temple Health financial assistance','hospital_assistance','Temple Health','Philadelphia region','free_or_low_cost','Free or reduced charges for qualifying medically necessary hospital care.','Financial eligibility and covered facilities/providers assessed through financial counseling.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Request financial assistance application through Temple billing office.','Not all separate physicians or bills necessarily covered; no current numerical threshold asserted here.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(87,'Jefferson Health financial assistance','hospital_assistance','Jefferson Health','Philadelphia region','free_or_low_cost','Financial assistance for eligible hospital bills.','Financial review and available insurance/government coverage must be addressed; entity-specific policy applies.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use the financial assistance page to contact the correct Jefferson facility billing office.','Policies may differ by affiliate; determine whether separate professional bills are included.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(88,'CHOP financial assistance','hospital_assistance','Children''s Hospital of Philadelphia','Philadelphia service area','free_if_eligible','Waiver of eligible patient responsibility after insurance/government assistance.','Generally income at or below 400% FPL, primary service-area residence, uninsured or participating insurance and other policy conditions.',400.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Call 800-974-2125; apply with income documents and seek Medicaid/CHIP when eligible.','Policy summary reviewed June 30, 2026; confirm covered providers, procedures and exceptions.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(89,'Medicare Savings Programs','health_coverage','Pennsylvania Medicaid / Medicare','Pennsylvania','free_if_eligible','Assistance with eligible Medicare premiums and, for some categories, cost sharing.','Income, assets and Medicare category rules apply; QMB, SLMB, QI and QDWI cover different costs.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply through Pennsylvania Medicaid; PA MEDI can help.','Not all Medicare care becomes free. QMB protections and eligibility differ from other categories.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(90,'Free special telephones','disability_equipment','TechOWL Free Special Phone Program','Pennsylvania','free_if_eligible','Adapted telephone equipment for qualifying communication disabilities.','Age 6+; Pennsylvania resident; disability prevents independent standard telephone use; individual income at/below 200% FPL; phone service or ability to obtain it.',200.0,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply through TechOWL Free Special Phone Program.','Equipment only; does not pay ongoing phone service. Functional fit and ability to learn equipment are assessed.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(91,'Assistive technology lending library','disability_equipment','TechOWL / Temple University','Pennsylvania','free','Short-term loan of assistive devices to test what works.','Pennsylvania residents with an assistive technology need.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Request a device through TechOWL library.','Typical loans five weeks, iPads nine weeks; mobility equipment may require local pickup. Loan, not ownership.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(92,'iCanConnect DeafBlind equipment and training','disability_equipment','TechOWL iCanConnect','Pennsylvania','free_if_eligible','Communication equipment and training for people with combined hearing and vision loss.','Combined hearing/vision disability and income eligibility; verification required.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use TechOWL DeafBlind application or email iCanConnectPA@temple.edu.','Eligibility assessment and approved device needs apply; not for hearing loss alone.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(93,'CreATe Together adaptive devices','disability_equipment','TechOWL','Pennsylvania','free_selected_services','Selected 3D-printed or fabricated assistive devices.','Pennsylvania residents; catalog requests limited to three items per household.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Order from TechOWL catalog or request custom-device consultation.','Standard eligible items are free; some larger custom projects require a contribution agreed in advance.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(94,'LAMP accessible library materials','disability_access','Free Library / Pennsylvania LAMP','Pennsylvania','free_if_eligible','Accessible audio, braille and other reading materials, with eligible playback equipment and postage-free delivery.','Qualifying print disability and required eligibility certification.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Enroll through Library of Accessible Media for Pennsylvanians.','Formats and equipment depend on program eligibility; materials are borrowed.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(95,'Pennsylvania state park entry','recreation','Pennsylvania DCNR','Pennsylvania','free','Admission to Pennsylvania state parks without an entrance fee.','Park visitors; park rules and operating hours apply.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Visit a state park using the DCNR directory.','Camping, cabins, rentals, permits and some activities have separate fees.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(96,'Fairmount Park compost and mulch pickup','gardening','Philadelphia Parks & Recreation','Philadelphia','free','Resident allotment of compost, mulch or wood chips when available.','Philadelphia residents; proof of residence; up to 30 gallons per day, twice weekly.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Visit Fairmount Park Organic Recycling Center, 3850 Ford Road; check current hours.','Bring containers and transport. Large quantities and disposal services can have charges.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(97,'TreePhilly yard trees','gardening','TreePhilly','Philadelphia','free_if_eligible','Tree for planting on eligible private yard property.','Philadelphia property planting location and giveaway requirements; permission required if not owner.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Register for a seasonal TreePhilly yard-tree giveaway.','Not a street-tree program. Limited trees and seasonal registration; recipient must care for tree.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(98,'Street-tree inspection and planting','gardening','Philadelphia Parks & Recreation','Philadelphia','free','Assessment and eligible street-tree planting, including necessary approved sidewalk opening.','Suitable public street-tree location, program approval and property permission as required.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Request a street tree through City/TreePhilly instructions.','Space, utilities, species and planting schedule constrain approval. Not any requested tree at any location.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(99,'Public swimming pools','recreation','Philadelphia Parks & Recreation','Philadelphia','free','Swimming at City public pools during scheduled public sessions.','Public visitors complying with pool supervision and safety rules.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use City pool opening schedule and local facility hours.','Outdoor pool service is seasonal; closures and staffing affect hours.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(100,'City pool swim lessons','recreation','Philadelphia Parks & Recreation','Philadelphia','free_if_eligible','Free beginner swim instruction at participating pools.','Age and registration criteria set by pool; children and selected adult offerings.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Contact participating pool during registration season.','Limited lesson spaces; adult instruction not offered at every site.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(101,'PA CareerLink employment services','employment','PA CareerLink','Pennsylvania','free','Job search, resume, interview and workforce navigation support.','Job seekers; specialized grants/training may have separate eligibility.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Create CareerLink account or contact Philadelphia CareerLink center.','Free basic services do not guarantee paid training, tuition funding or a job.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(102,'SkillUp PA online job training','employment','Pennsylvania Labor & Industry / PA CareerLink','Pennsylvania','free','Free online training courses through SkillUp PA.','PA job seekers accessing the program through CareerLink registration.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Register through the state SkillUp service page.','Available course library and credential/exam inclusion vary; no job guarantee.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(103,'City recycling bins','household','Philadelphia sanitation convenience centers','Philadelphia','free','Residential recycling bins.','City resident with photo identification and proof of address; one bin per visit, two per year per household.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Visit a sanitation convenience center; call ahead for stock.','Supply dependent; limits apply.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(104,'ACCESS cultural admission','culture','Art-Reach partner venues','Philadelphia region','free_or_low_cost','Discount admission at participating museums, gardens, theaters and cultural sites.','Qualifying state ACCESS/EBT cardholders or eligible disability ACCESS membership; venue and guest rules apply.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Check Art-Reach ACCESS venue list and present qualifying card and required ID.','Special events may be excluded. A separately purchased Art-Reach card has a membership cost; do not confuse it with a state benefits card.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(105,'PHL City ID senior waiver and low-cost card','identification','Philadelphia PHL City ID','Philadelphia','free_or_low_cost','Municipal photo ID with age-based fee.','Philadelphia residents age 13+ meeting identity and residency documentation rules.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Schedule City ID appointment and bring accepted documents.','Municipal ID is not a driver license or proof of immigration status; document rules still apply.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(106,'Birth certificate homeless fee waiver','identification','Pennsylvania Department of Health','Pennsylvania births','free_if_eligible','Fee-waived Pennsylvania birth certificate for qualifying people experiencing homelessness.','Eligible individual experiencing homelessness; application and advocate/identity verification rules apply.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Use state homelessness fee-waiver birth-certificate form.','Only applicable vital records; not a waiver of every ID-related expense.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(107,'Veterans Temporary Assistance','veterans','Pennsylvania DMVA','Pennsylvania','free_if_eligible','Emergency financial assistance for necessities such as food, shelter, fuel and clothing.','Qualifying Pennsylvania veterans or beneficiaries with immediate financial need and program service criteria.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Contact county veterans affairs office or DMVA VTA program; do not email sensitive documents to general inquiry address.','Up to $1,600 in a 12-month period; application and financial review required.','published_intake_unconfirmed','2026-11-09',2);
INSERT INTO benefits VALUES(108,'Property Tax/Rent Rebate','tax_relief','Pennsylvania Department of Revenue','Pennsylvania','free_if_eligible','Rebate of eligible property taxes or rent paid.','Age 65+, widow/widower 50+, or adult with disability; published annual household income limit $48,110 with program exclusions.',NULL,NULL,'See eligibility; no insurance requirement inferred unless stated.','Apply free through myPATH or an authorized assistance site.','Use correct claim year, income definition and deadline; no need to pay a commercial application service.','published_intake_unconfirmed','2026-11-09',2);
