INSERT INTO research_notes VALUES(1,'PrEP total cost','Overview says free; TelePrEP detailed FAQ says little or no cost.','Confirm drug/formulation, visits, labs and delivery separately with navigator.');
INSERT INTO research_notes VALUES(2,'Birth control','City clinic uninsured care is sliding-scale; insurance and PA program offer distinct pathways.','Check plan network, prescription, selected method and eligibility.');
INSERT INTO research_notes VALUES(3,'Source freshness','Health Center 5 closure supersedes older pickup listing. Resource Hubs relocated into NCACs in 2026.','Use live location pages before traveling.');
INSERT INTO research_notes VALUES(4,'Mazzoni cost conflict','CDC listing includes free tests, while current provider page says insurance/sliding scale.','Ask whether specific navigation or outreach tests remain free.');
INSERT INTO research_notes VALUES(5,'Income changes','SPBP now lists 350% FPL, not older 500%; PA Medicaid flags 2027 changes.','Refresh thresholds and policy at application time.');
INSERT INTO research_notes VALUES(6,'Coverage breadth','Expanded housing, utilities, food, disability equipment, legal help, cultural access and veterans support now included.','Remaining gaps include comprehensive restorative dental and vision care, individual hospital affiliate policies, veteran healthcare eligibility, home-care waivers and complete tax-credit inventory.');
INSERT INTO research_notes VALUES(7,'Additional healthcare gaps','Added Temple, Jefferson and CHOP assistance, legal health advocacy and disability devices; some financial schedules and intake capacity remain unconfirmed.','Compare actual bills and facility-specific policy before assuming full coverage; audit additional clinics and restorative dental services.');
INSERT INTO research_notes VALUES(8,'No personal profile','This public catalog stores no resident profiles or individual eligibility decisions.','Optional future filtering can identify likely matches without treating it as an eligibility ruling.');
INSERT INTO research_notes VALUES(9,'Programs not equated with universal entitlements','Free access may depend on approved eligibility, stock, clinical judgment, funding and appointment capacity.','Confirm enrollment and itemized patient cost before obtaining care.');
INSERT INTO research_notes VALUES(10,'Seasonal benefits','SUN Bucks 2026 application deadline and outdoor swimming season have passed. LIHEAP 2026-27 is seasonal.','Use availability field; refresh next-season dates before applying.');
INSERT INTO research_notes VALUES(11,'Funding transparency','Public operation, a state eligibility card and historical grants do not establish that a current service is fully taxpayer-funded.','Funding labels are conservative; audit grant budgets where exact tax financing matters.');
INSERT INTO research_notes VALUES(12,'Counts versus programs','Several entries are separate components or access routes within one program, such as LIHEAP cash/crisis and pool access/lessons.','Do not present row count as distinct independent government programs.');
INSERT INTO research_notes VALUES(13,'Outstanding source gaps','A library Experience Pass URL redirected to a general program page; current availability was not verified. Indego pricing and some reused-equipment fees were not confirmed.','Excluded these unconfirmed offers rather than treating them as active free benefits.');
